MEDIA_PLUGIN_HTTPSOURCE_1.0 {
  global:
    /* dlsym entries - must keep exact names */
    GetMinSniffBufferSize;
    SniffStreamProtocolFromData;
    GetStreamResourceParser;
    CreateNetworkClient;
    CreateNetworkClientExt;
    register_HttpSource;
    unregister_HttpSource;

    /* __cfi_check is handled by build/config/sanitizers/cfi.versionscript,
       do not declare here to avoid version reassignment conflict */

    extern "C++" {
      /* HttpSourcePlugin: polymorphic class with virtual methods */
      OHOS::Media::Plugins::HttpPlugin::HttpSourcePlugin::*;
      *vtable*for*OHOS*Media*Plugins*HttpPlugin*HttpSourcePlugin*;

      /* StreamProtocolSniffer: non-polymorphic (static methods only, no vtable) */
      OHOS::Media::Plugins::HttpPlugin::StreamProtocolSniffer::*;

      /* StreamResourceParser: polymorphic class with virtual methods */
      OHOS::Media::Plugins::HttpPlugin::StreamResourceParser::*;
      *vtable*for*OHOS*Media*Plugins*HttpPlugin*StreamResourceParser*;
    };

  local:
    *;
};
